<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>EMBERLINE — Foundry Yard</title>
<style>
  :root {
    --canvas: #20242c;
    --surface: #171a20;
    --panel: #1e222a;
    --hairline: #333945;
    --ink: #ece7db;
    --muted: #9aa3ae;
    --accent: #f0a830;
    --accent2: #4da3ff;
    --danger: #ff5a4d;
    --good: #7dd87d;
    --radius: 4px;
    --font-ui: system-ui, -apple-system, 'Segoe UI', sans-serif;
    --font-readout: ui-monospace, 'SF Mono', Menlo, Consolas, monospace;
  }
  * { box-sizing: border-box; }
  html, body { margin: 0; height: 100%; overflow: hidden; background: var(--canvas); color: var(--ink); font-family: var(--font-ui); }
  #game, #game canvas { position: fixed; inset: 0; display: block; }
  #hud { position: fixed; inset: 0; pointer-events: none; z-index: 5; }

