  #crosshair i:nth-child(2) { left: 12px; bottom: 0; width: 2px; height: 8px; }
  #crosshair i:nth-child(3) { top: 12px; left: 0; height: 2px; width: 8px; }
  #crosshair i:nth-child(4) { top: 12px; right: 0; height: 2px; width: 8px; }
  #crosshair i:nth-child(5) { left: 12px; top: 12px; width: 2px; height: 2px; }
  #crosshair.spread i:nth-child(1) { transform: translateY(calc(var(--gap, 0) * -1px)); }
  #crosshair.spread i:nth-child(2) { transform: translateY(calc(var(--gap, 0) * 1px)); }
  #crosshair.spread i:nth-child(3) { transform: translateX(calc(var(--gap, 0) * -1px)); }
