  .panel { width: min(560px, 100%); padding: 32px; background: var(--panel); border: 1px solid var(--hairline); border-radius: var(--radius); }
  .panel h1 { margin: 0 0 4px; font-size: 40px; line-height: 1; font-weight: 700; letter-spacing: .02em; }
  .panel h1 span { color: var(--accent); }
  .panel h2 { margin: 0 0 8px; font-size: 24px; }
  .panel p { margin: 0 0 20px; font-size: 15px; line-height: 1.55; color: var(--muted); }
  .panel button { font: inherit; font-weight: 600; padding: 12px 18px; border: 1px solid var(--accent); border-radius: var(--radius); background: var(--accent); color: #17130a; cursor: pointer; }
  .panel button:hover { background: var(--ink); border-color: var(--ink); }
  .keys { margin: 22px 0 0; padding: 0; list-style: none; display: grid; grid-template-columns: 1fr 1fr; gap: 7px 16px; font-size: 13px; color: var(--muted); }
  .keys kbd { min-width: 22px; padding: 2px 6px; border: 1px solid var(--hairline); border-radius: 3px; font-family: var(--font-readout); font-size: 11px; color: var(--ink); text-align: center; display: inline-block; }
  .score-table { width: 100%; border-collapse: collapse; font-family: var(--font-readout); font-size: 13px; margin: 8px 0 18px; }
  .score-table th, .score-table td { padding: 4px 8px; text-align: left; border-bottom: 1px solid var(--hairline); }
  .score-table th { color: var(--muted); font-weight: 500; }
  .score-table .vg { color: var(--accent2); } .score-table .hw { color: var(--danger); }

  #buymenu { position: fixed; inset: 0; display: grid; place-items: center; z-index: 8; background: rgba(14,16,20,.72); }
  #buymenu[hidden] { display: none; }
  #buymenu .panel { width: min(680px, 96%); }
  .shop { display: grid; grid-template-columns: repeat(3, 1fr); gap: 8px; }
  .shop button { text-align: left; padding: 10px 12px; background: var(--surface); color: var(--ink); border: 1px solid var(--hairline); border-radius: var(--radius); cursor: pointer; font: inherit; }
  .shop button:hover:not(:disabled) { border-color: var(--accent); }
  .shop button:disabled { opacity: .38; cursor: default; }
  .shop button .nm { display: block; font-size: 14px; font-weight: 600; }
  .shop button .ds { display: block; font-size: 11px; color: var(--muted); margin-top: 2px; }
  .shop button .pr { display: block; font-size: 13px; color: var(--accent); margin-top: 4px; font-family: var(--font-readout); }
  .shop button.owned { border-color: var(--good); }
  #buy-money { font-family: var(--font-readout); color: var(--accent); font-size: 15px; margin-bottom: 12px; }
  @media (prefers-reduced-motion: reduce) { #banner, #toast, #dmg { transition-duration: .01ms; } }
</style>
