  const instances = {};
  function getInstance(id) {
    if (!instances[id]) {
      const d = WEAPONS[id];
      instances[id] = { def: d, mag: d.mag, reserve: d.reserve, reloading: false, reloadEnd: 0, lastShot: -1e9, bloom: 0 };
