        hitAny = true;
        if (hit.part === 'head') headshot = true;
        totalDmg += hit.damage;
        if (hit.killed) killed = hit.bot;
      } else if (hit.part === 'world') {
        effects.impact(hit.px, hit.py, hit.pz, 0xffc46a, 8);
