      for (let i = 0; i < world.colliders.length; i++) {
        const c = world.colliders[i];
        if (g.pos.x > c.minX - 0.12 && g.pos.x < c.maxX + 0.12 && g.pos.y > c.minY - 0.12 && g.pos.y < c.maxY + 0.12 && g.pos.z > c.minZ - 0.12 && g.pos.z < c.maxZ + 0.12) {
