          else if (m === dzl) { g.pos.z = c.minZ - 0.12; g.vel.z = -Math.abs(g.vel.z) * 0.4; }
          else if (m === dzr) { g.pos.z = c.maxZ + 0.12; g.vel.z = Math.abs(g.vel.z) * 0.4; }
          else if (m === dyl) { g.pos.y = c.minY - 0.12; g.vel.y = -Math.abs(g.vel.y) * 0.4; }
